def priority(task, state, m=5.0, b=2.0, thresh=0.5):
    # MOD normally; if queue is congested, switch to tenant-weighted SPT with aging
    if state.queue_len > thresh * state.capacity / max(task.resource_need, 1e-6):
        tier = m if task.tenant == 'premium' else 1.0
        wait = state.now - task.release
        return tier / max(task.estimated_runtime, 1e-6) * (1 + b * wait / max(task.estimated_runtime, 1e-6))
    return -max(task.due, state.now + task.estimated_runtime)

