import math
def priority(task, state, m=5.0, hi=0.7, lo=0.3, k=1.0):
    est = max(task.estimated_runtime, 1e-6)
    tier = m if task.tenant == 'premium' else 1.0
    load = state.queue_work / max(state.capacity, 1e-6)
    # under heavy load, favor SPT strongly; under light load use slack/ATC
    if load >= hi:
        return tier / est
    if load <= lo:
        slack = max(0.0, task.due - est - state.now)
        return tier * task.weight / est * math.exp(-slack / (k * max(state.mean_est, 1e-6)))
    # blended regime
    slack = max(0.0, task.due - est - state.now)
    atc = task.weight / est * math.exp(-slack / (k * max(state.mean_est, 1e-6)))
    spt = 1.0 / est
    return tier * (0.5 * atc + 0.5 * spt)

