import math
def priority(task, state, m=5.0, c=3.0, k=2.0):
    est = max(task.estimated_runtime, 1e-6)
    tier = m if task.tenant == 'premium' else 1.0
    wait = max(0.0, state.now - task.release)
    ratio = wait / est
    if ratio >= c:
        return 1e6 + tier / est
    slack = max(0.0, task.due - est - state.now)
    return tier / est * math.exp(-slack / (k * max(state.mean_est, 1e-6)))

