def priority(task, state, m=8.0, b=1.0, thresh=0.5, q=0.5):
    est = max(task.estimated_runtime, 1e-6)
    wait = state.now - task.release
    tier = m if task.tenant == 'premium' else 1.0
    age = 1.0 + b * wait / est
    frac = state.free / max(state.capacity, 1e-6)
    mem = max(task.resource_need, 1e-6)
    if frac < thresh:
        return tier * task.weight / (est * est) * age / (mem ** q)
    return tier * task.weight / est * age / (mem ** q)

