def priority(task, state, m=5.0, k=2.0, guard=2.0):
    slack = max(0.0, task.due - task.estimated_runtime - state.now)
    tier = m if task.tenant == 'premium' else 1.0
    ratio = (state.now - task.release) / max(task.estimated_runtime, 1e-6)
    base = tier * task.weight / max(task.estimated_runtime, 1e-6) * math.exp(-slack / (k * max(state.mean_est, 1e-6)))
    return base + (1e6 if ratio >= guard else 0.0)

def priority(task, state, m=5.0, k=2.0, q=0.5):
    slack = max(0.0, task.due - task.estimated_runtime - state.now)
    tier = m if task.tenant == 'premium' else 1.0
    pressure = state.queue_work / max(state.capacity, 1e-6)
    kk = k * (1.0 + q * pressure)
    return tier * task.weight / max(task.estimated_runtime, 1e-6) * math.exp(-slack / (kk * max(state.mean_est, 1e-6)))

def priority(task, state, m=5.0, k=2.0, late=1.0):
    slack = max(0.0, task.due - task.estimated_runtime - state.now)
    tier = m if task.tenant == 'premium' else 1.0
    overdue = max(0.0, state.now + task.estimated_runtime - task.due)
    base = tier * task.weight / max(task.estimated_runtime, 1e-6) * math.exp(-slack / (k * max(state.mean_est, 1e-6)))
    return base * (1.0 + late * overdue / max(task.estimated_runtime, 1e-6))

