def priority(task, state, m=5.0, b=1.0, thresh=0.3):
    est = max(task.estimated_runtime, 1e-6)
    tier = m if task.tenant == 'premium' else 1.0
    wait = state.now - task.release
    load = state.queue_work / max(state.capacity, 1e-6)
    # Under high memory pressure, protect premiums and short jobs via SPT;
    # under low pressure, let aging dominate to clear long waiters.
    if load > thresh:
        return tier / est + b * wait / (est * est)
    return tier * (1.0 + b * wait) / est

