import math
def priority(task, state, m=3.5, k=2.5, lateness=0.5):
    est = max(task.estimated_runtime, 1e-6)
    tier = m if task.tenant == 'premium' else 1.0
    slack = task.due - est - state.now
    if slack < 0:
        return tier * task.weight / est * (1.0 + lateness * (-slack) / est)
    urgency = math.exp(-slack / (k * max(state.mean_est, 1e-6)))
    return tier * task.weight / est * urgency

